'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { getAllNewsAdmin, NewsItem, getTodayNews, getMostViewedNews, getPendingComments, getUnreadTips, CommentWithNews, Tip } from '@/lib/supabase'
import { supabase } from '@/lib/supabase'

export default function AdminDashboard() {
  const [news, setNews] = useState<NewsItem[]>([])
  const [todayNews, setTodayNews] = useState<NewsItem[]>([])
  const [mostViewed, setMostViewed] = useState<NewsItem[]>([])
  const [pendingComments, setPendingComments] = useState<CommentWithNews[]>([])
  const [tips, setTips] = useState<Tip[]>([])
  const [adminChecked, setAdminChecked] = useState(false)
  const [isUserAdmin, setIsUserAdmin] = useState(false)
  const [userEmail, setUserEmail] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState<string>('all')
  
  const [stats, setStats] = useState({
    total: 0,
    published: 0,
    draft: 0,
    archived: 0,
    scheduled: 0,
    featured: 0,
    thisMonth: 0,
    today: 0,
    categories: 6,
  })

  // Admin kontrolü - sadece bir kez çalışmalı
  useEffect(() => {
    let mounted = true // Component unmount kontrolü

    const checkAdminStatus = async () => {
      if (!mounted) return

      if (!supabase) {
        console.error('❌ Supabase not initialized')
        if (mounted) {
          setAdminChecked(true)
          setIsUserAdmin(false)
        }
        return
      }

      try {
        const { data: { session }, error: sessionError } = await supabase.auth.getSession()
        
        if (!mounted) return

        if (sessionError || !session?.user) {
          setAdminChecked(true)
          setIsUserAdmin(false)
          // Redirect'i sadece bir kez yap
          if (window.location.pathname !== '/auth/login') {
            window.location.href = '/auth/login?redirect=/admin'
          }
          return
        }

        const { data: adminUser, error: adminError } = await supabase
          .from('admins')
          .select('user_id, role')
          .eq('user_id', session.user.id)
          .maybeSingle()

        if (!mounted) return

        if (adminError && adminError.code !== 'PGRST116') {
          console.error('Admin check error:', adminError)
        }

        // Sadece admin/super_admin erişebilir (role kolonu yoksa legacy admin kabul)
        const role = (adminUser as any)?.role as string | undefined
        const allowed = !!adminUser && (role === 'admin' || role === 'super_admin' || !role)

        if (allowed) {
          setUserEmail(session.user.email || null)
          setIsUserAdmin(true)
          setAdminChecked(true)
        } else {
          setUserEmail(session.user.email || null)
          setIsUserAdmin(false)
          setAdminChecked(true)
          // Redirect'i sadece bir kez yap
          if (window.location.pathname !== '/') {
            setTimeout(() => {
              if (mounted) {
                window.location.href = '/'
              }
            }, 2000)
          }
        }
      } catch (err) {
        console.error('Admin check error:', err)
        if (mounted) {
          setIsUserAdmin(false)
          setAdminChecked(true)
          if (window.location.pathname !== '/') {
            setTimeout(() => {
              if (mounted) {
                window.location.href = '/'
              }
            }, 2000)
          }
        }
      }
    }

    checkAdminStatus()

    return () => {
      mounted = false // Cleanup
    }
  }, []) // Boş dependency array - sadece mount'ta çalış

  // Dashboard verilerini yükle - sadece admin onaylandıktan sonra
  useEffect(() => {
    if (!adminChecked || !isUserAdmin) return

    let mounted = true

    const fetchDashboardData = async () => {
      try {
        const allNews = await getAllNewsAdmin()
        const today = await getTodayNews()
        const mostViewedNews = await getMostViewedNews(5)
        const pending = await getPendingComments()
        const unreadTips = await getUnreadTips()

        if (!mounted) return

        setNews(allNews)
        setTodayNews(today)
        setMostViewed(mostViewedNews)
        setPendingComments(pending)
        setTips(unreadTips.slice(0, 5))

        const thisMonth = new Date()
        thisMonth.setMonth(thisMonth.getMonth() - 1)

        const filtered = allNews.filter(n => {
          const pubDate = new Date(n.published_at || n.created_at)
          return pubDate > thisMonth
        })

        setStats({
          total: allNews.length,
          published: allNews.filter(n => n.status === 'published' || (!n.status && n.is_published)).length,
          draft: allNews.filter(n => n.status === 'draft' || (!n.status && n.is_draft)).length,
          archived: allNews.filter(n => n.status === 'archived').length,
          scheduled: allNews.filter(n => n.scheduled_publish_at && new Date(n.scheduled_publish_at) > new Date()).length,
          featured: allNews.filter(n => n.featured).length,
          thisMonth: filtered.length,
          today: today.length,
          categories: 6,
        })
      } catch (error) {
        console.error('Error fetching dashboard data:', error)
      }
    }

    fetchDashboardData()

    return () => {
      mounted = false
    }
  }, [adminChecked, isUserAdmin]) // Sadece adminChecked ve isUserAdmin değiştiğinde çalış

  // Loading state - admin check tamamlanana kadar bekle
  if (!adminChecked) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="text-white text-center">
          <div className="text-xl mb-2">Yükleniyor...</div>
          <div className="text-sm text-gray-400">Admin kontrolü yapılıyor</div>
        </div>
      </div>
    )
  }

  // Admin değilse erişim reddedildi göster
  if (!isUserAdmin) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="text-white text-center">
          <h2 className="text-2xl font-bold mb-4">Erişim Reddedildi</h2>
          <p className="text-gray-400">Bu hesap admin yetkisine sahip değil.</p>
          {userEmail && <p className="text-sm text-gray-500 mt-2">Email: {userEmail}</p>}
          <p className="text-sm text-gray-500 mt-4">Ana sayfaya yönlendiriliyorsunuz...</p>
        </div>
      </div>
    )
  }

  const filteredNews = statusFilter === 'all' 
    ? news 
    : news.filter(item => {
        if (statusFilter === 'published') return item.status === 'published' || (!item.status && item.is_published)
        if (statusFilter === 'draft') return item.status === 'draft' || (!item.status && item.is_draft)
        if (statusFilter === 'archived') return item.status === 'archived'
        if (statusFilter === 'scheduled') return item.scheduled_publish_at && new Date(item.scheduled_publish_at) > new Date()
        return true
      })

  const getStatusBadge = (item: NewsItem) => {
    const status = item.status || (item.is_draft ? 'draft' : item.is_published ? 'published' : 'draft')
    
    switch (status) {
      case 'published':
        return <span className="bg-green-600 px-2 py-1 rounded text-xs">Yayında</span>
      case 'draft':
        return <span className="bg-yellow-600 px-2 py-1 rounded text-xs">Taslak</span>
      case 'archived':
        return <span className="bg-gray-600 px-2 py-1 rounded text-xs">Arşiv</span>
      case 'removed':
        return <span className="bg-red-600 px-2 py-1 rounded text-xs">Kaldırıldı</span>
      default:
        return <span className="bg-gray-600 px-2 py-1 rounded text-xs">Taslak</span>
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white">
      {/* Header */}
      <div className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold">DikiliHaber Admin Paneli</h1>
              <p className="text-gray-400 mt-1">Profesyonel Haber Yönetim Sistemi</p>
            </div>
            <div className="text-right">
              <p className="text-sm text-gray-400">Hoş geldiniz</p>
              <p className="text-sm font-medium">{userEmail}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <div className="bg-gradient-to-br from-blue-600 to-blue-700 rounded-lg p-6 shadow-lg">
            <p className="text-blue-100 text-sm mb-2">Toplam Haberler</p>
            <p className="text-4xl font-bold">{stats.total}</p>
          </div>
          <div className="bg-gradient-to-br from-green-600 to-green-700 rounded-lg p-6 shadow-lg">
            <p className="text-green-100 text-sm mb-2">Yayında</p>
            <p className="text-4xl font-bold">{stats.published}</p>
          </div>
          <div className="bg-gradient-to-br from-yellow-600 to-yellow-700 rounded-lg p-6 shadow-lg">
            <p className="text-yellow-100 text-sm mb-2">Taslaklar</p>
            <p className="text-4xl font-bold">{stats.draft}</p>
          </div>
          <div className="bg-gradient-to-br from-purple-600 to-purple-700 rounded-lg p-6 shadow-lg">
            <p className="text-purple-100 text-sm mb-2">Planlanmış</p>
            <p className="text-4xl font-bold">{stats.scheduled}</p>
          </div>
          <div className="bg-gradient-to-br from-orange-600 to-orange-700 rounded-lg p-6 shadow-lg">
            <p className="text-orange-100 text-sm mb-2">Öne Çıkan</p>
            <p className="text-4xl font-bold">{stats.featured}</p>
          </div>
          <div className="bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-lg p-6 shadow-lg">
            <p className="text-indigo-100 text-sm mb-2">Bu Ay</p>
            <p className="text-4xl font-bold">{stats.thisMonth}</p>
          </div>
          <div className="bg-gradient-to-br from-pink-600 to-pink-700 rounded-lg p-6 shadow-lg">
            <p className="text-pink-100 text-sm mb-2">Arşiv</p>
            <p className="text-4xl font-bold">{stats.archived}</p>
          </div>
          <div className="bg-gradient-to-br from-cyan-600 to-cyan-700 rounded-lg p-6 shadow-lg">
            <p className="text-cyan-100 text-sm mb-2">Kategoriler</p>
            <p className="text-4xl font-bold">{stats.categories}</p>
          </div>
          <div className="bg-gradient-to-br from-emerald-600 to-emerald-700 rounded-lg p-6 shadow-lg">
            <p className="text-emerald-100 text-sm mb-2">Bugün Girilen</p>
            <p className="text-4xl font-bold">{stats.today}</p>
          </div>
        </div>

        {/* Dashboard Content Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
          {/* En Çok Okunan 5 Haber */}
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-bold mb-4 flex items-center justify-between">
              <span>📈 En Çok Okunan Haberler</span>
              <span className="text-sm text-gray-400 font-normal">Top 5</span>
            </h2>
            <div className="space-y-3">
              {mostViewed.length === 0 ? (
                <p className="text-gray-400 text-sm">Henüz görüntülenme verisi yok.</p>
              ) : (
                mostViewed.map((item, idx) => (
                  <Link
                    key={item.id}
                    href={`/news/${item.slug}`}
                    className="block p-3 bg-gray-700 rounded-lg hover:bg-gray-600 transition group"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-blue-400 font-bold">#{idx + 1}</span>
                          <span className="text-xs bg-blue-600 px-2 py-0.5 rounded">{item.category}</span>
                        </div>
                        <p className="text-sm font-medium group-hover:text-blue-400 transition line-clamp-2">{item.title}</p>
                        <p className="text-xs text-gray-400 mt-1">👁️ {(item as any).views || 0} görüntülenme</p>
                      </div>
                    </div>
                  </Link>
                ))
              )}
            </div>
          </div>

          {/* Bekleyen Yorumlar */}
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-bold mb-4 flex items-center justify-between">
              <span>💬 Bekleyen Yorumlar</span>
              <Link href="/admin/comments" className="text-sm text-blue-400 hover:underline font-normal">
                Tümünü Gör →
              </Link>
            </h2>
            <div className="space-y-3">
              {pendingComments.length === 0 ? (
                <p className="text-gray-400 text-sm">Bekleyen yorum yok. ✅</p>
              ) : (
                pendingComments.slice(0, 5).map((comment) => (
                  <div key={comment.id} className="p-3 bg-gray-700 rounded-lg">
                    <p className="text-sm mb-2 line-clamp-2">{comment.content}</p>
                    <div className="flex items-center justify-between text-xs text-gray-400">
                      <span>{comment.user_name || 'Anonim'}</span>
                      <span>{new Date(comment.created_at).toLocaleDateString('tr-TR')}</span>
                    </div>
                    {comment.news_slug && (
                      <Link
                        href={`/news/${comment.news_slug}`}
                        className="text-xs text-blue-400 hover:underline mt-1 inline-block"
                      >
                        {comment.news_title}
                      </Link>
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* Son İhbarlar */}
        {tips.length > 0 && (
          <div className="bg-gray-800 rounded-lg p-6 mb-8">
            <h2 className="text-xl font-bold mb-4 flex items-center justify-between">
              <span>📢 Son İhbarlar</span>
              <span className="text-sm text-orange-400 font-normal">{tips.filter(t => !t.is_read).length} Okunmamış</span>
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {tips.map((tip) => (
                <div
                  key={tip.id}
                  className={`p-4 rounded-lg border-l-4 ${
                    tip.is_read ? 'bg-gray-700 border-gray-600' : 'bg-orange-900/20 border-orange-500'
                  }`}
                >
                  <div className="flex items-start justify-between mb-2">
                    <h3 className="font-semibold text-sm">{tip.title}</h3>
                    {!tip.is_read && <span className="bg-orange-600 px-2 py-0.5 rounded text-xs">YENİ</span>}
                  </div>
                  {tip.description && <p className="text-sm text-gray-400 mb-2 line-clamp-2">{tip.description}</p>}
                  <div className="flex items-center gap-4 text-xs text-gray-400">
                    {tip.category && <span>📂 {tip.category}</span>}
                    {tip.location && <span>📍 {tip.location}</span>}
                    {tip.is_anonymous && <span>🔒 Anonim</span>}
                    <span>{new Date(tip.created_at).toLocaleDateString('tr-TR')}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Quick Actions */}
        <div className="bg-gray-800 rounded-lg p-6 mb-8">
          <h2 className="text-xl font-bold mb-4">Hızlı İşlemler</h2>
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
            <Link href="/admin/news/new" className="bg-blue-600 hover:bg-blue-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              ➕ Yeni Haber
            </Link>
            <Link href="/admin/news" className="bg-green-600 hover:bg-green-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              📝 Haberler
            </Link>
            <Link href="/admin/comments" className="bg-orange-600 hover:bg-orange-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              💬 Yorumlar
            </Link>
            <Link href="/admin/tips" className="bg-red-600 hover:bg-red-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              📢 İhbarlar {tips.filter(t => !t.is_read).length > 0 && `(${tips.filter(t => !t.is_read).length})`}
            </Link>
            <Link href="/admin/users" className="bg-purple-600 hover:bg-purple-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              👥 Kullanıcılar
            </Link>
            <Link href="/admin/ads" className="bg-yellow-600 hover:bg-yellow-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              📢 Reklamlar
            </Link>
            <button className="bg-indigo-600 hover:bg-indigo-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              📊 Analitik
            </button>
            <button className="bg-pink-600 hover:bg-pink-700 rounded-lg p-4 text-center font-semibold transition transform hover:scale-105">
              ⚙️ Ayarlar
            </button>
          </div>
        </div>

        {/* News Table with Filters */}
        <div className="bg-gray-800 rounded-lg p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold">Haber Yönetimi</h2>
            <div className="flex gap-2">
              <button
                onClick={() => setStatusFilter('all')}
                className={`px-4 py-2 rounded ${statusFilter === 'all' ? 'bg-blue-600' : 'bg-gray-700'} transition`}
              >
                Tümü
              </button>
              <button
                onClick={() => setStatusFilter('published')}
                className={`px-4 py-2 rounded ${statusFilter === 'published' ? 'bg-green-600' : 'bg-gray-700'} transition`}
              >
                Yayında
              </button>
              <button
                onClick={() => setStatusFilter('draft')}
                className={`px-4 py-2 rounded ${statusFilter === 'draft' ? 'bg-yellow-600' : 'bg-gray-700'} transition`}
              >
                Taslak
              </button>
              <button
                onClick={() => setStatusFilter('scheduled')}
                className={`px-4 py-2 rounded ${statusFilter === 'scheduled' ? 'bg-purple-600' : 'bg-gray-700'} transition`}
              >
                Planlanmış
              </button>
              <button
                onClick={() => setStatusFilter('archived')}
                className={`px-4 py-2 rounded ${statusFilter === 'archived' ? 'bg-pink-600' : 'bg-gray-700'} transition`}
              >
                Arşiv
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="border-b border-gray-700">
                <tr>
                  <th className="text-left py-3 px-4">Başlık</th>
                  <th className="text-left py-3 px-4">Kategori</th>
                  <th className="text-left py-3 px-4">Durum</th>
                  <th className="text-left py-3 px-4">Kaynak</th>
                  <th className="text-left py-3 px-4">Tarih</th>
                  <th className="text-left py-3 px-4">İşlemler</th>
                </tr>
              </thead>
              <tbody>
                {filteredNews.length === 0 ? (
                  <tr className="border-b border-gray-700 hover:bg-gray-700/50">
                    <td colSpan={6} className="text-center py-8 text-gray-400">
                      {statusFilter === 'all' ? (
                        <>Henüz haber yok. <Link href="/admin/news/new" className="text-blue-400 hover:underline">Yeni haber oluşturun</Link></>
                      ) : (
                        'Bu durumda haber bulunamadı.'
                      )}
                    </td>
                  </tr>
                ) : (
                  filteredNews.slice(0, 20).map((item) => (
                    <tr key={item.id} className="border-b border-gray-700 hover:bg-gray-700/50 transition">
                      <td className="py-3 px-4">
                        <div className="max-w-xs truncate font-medium">{item.title}</div>
                        {item.tags && item.tags.length > 0 && (
                          <div className="flex gap-1 mt-1 flex-wrap">
                            {item.tags.slice(0, 3).map((tag, idx) => (
                              <span key={idx} className="text-xs bg-gray-700 px-2 py-0.5 rounded">#{tag}</span>
                            ))}
                          </div>
                        )}
                      </td>
                      <td className="py-3 px-4">
                        <span className="bg-blue-600 px-2 py-1 rounded text-xs">{item.category}</span>
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-2">
                          {getStatusBadge(item)}
                          {item.featured && <span className="text-yellow-400">⭐</span>}
                          {item.scheduled_publish_at && new Date(item.scheduled_publish_at) > new Date() && (
                            <span className="text-purple-400 text-xs">📅</span>
                          )}
                        </div>
                      </td>
                      <td className="py-3 px-4 text-sm text-gray-400">
                        {item.source || 'Dikili Haber'}
                      </td>
                      <td className="py-3 px-4 text-sm text-gray-400">
                        {new Date(item.published_at || item.created_at).toLocaleDateString('tr-TR')}
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex gap-2">
                          <Link href={`/news/${item.slug}`} className="text-blue-400 hover:underline text-sm" target="_blank">
                            👁️ Görüntüle
                          </Link>
                          <Link href={`/admin/news/edit/${item.id}`} className="text-yellow-400 hover:underline text-sm">
                            ✏️ Düzenle
                          </Link>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  )
}
